  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Omadacycline absolute bioavailability was 34.5% in healthy adults, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Hydrocortisone absolute oral bioavailability was estimated at 0.344 (34.4%) from 20 mg oral vs IV bolus in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "CGP 43371 oral bioavailability was 9% in healthy men after an 800-mg capsule dose, arguing for F < 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred evidence, including the highest-scoring molecule, shows absolute oral bioavailability values above 20%; one lower-scoring molecule reports 9% bioavailability. The balance supports high oral bioavailability.",
  "evidence_gaps": [
    "Molecule 3 provides only qualitative 'may be low' evidence, not an affirmative threshold-relevant measurement.",
    "Molecule 2 provides a contradictory low F=9%, but it is a single molecule with lower assay-transfer score than the main supportive evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

